def solve():
	n = int(input())
	nums = list(map(int, input().split()))
	ans = n * (n * 2 + 1)
	visited = [0] * n
	path = []
	pt = 0
	flag = False
	while not visited[pt]:
		path.append(pt)
		visited[pt] = 1
		pt += nums[pt]
		if not 0 <= pt < n:
			break
	else:
		ans -= (n - sum(visited)) * (2 * n + 1)
		flag = True
	cnt = sum(visited)
	if flag:
		ans -= cnt * cnt
	else:
		ans -= (1 + cnt) * cnt // 2
	new_visited = [0] * n
	note = visited[:]
	for i in range(n):
		if not note[i]:
			tmp = []
			f = False
			while not note[i]:
				tmp.append(i)
				note[i] = 1
				i += nums[i]
				if not 0 <= i < n:
					break
				if note[i] and new_visited[i] >= 0 or visited[i]:
					f = True
			if f:
				if new_visited[i]:
					i = new_visited[i] - 1
				for x in tmp:
					new_visited[x] = i + 1
			else:
				for x in tmp:
					new_visited[x] = -1
	path_note = {v: i for (i, v) in enumerate(path)}
	for i in range(n):
		if not visited[i]:
			if new_visited[i] != -1:
				if visited[new_visited[i] - 1] == 0 or flag:
					ans -= cnt
				else:
					ans -= cnt - path_note[new_visited[i] - 1]
	print(ans)
for _ in range(int(input())):
	solve()
